1	import { randomUUID } from "node:crypto";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	import { z } from "zod";
4	import { calendarDate } from "@/lib/finance/calendar";
5	import { formatMoney } from "@/lib/finance/format";
6	import { loadWorkspaceSettings } from "@/lib/settings";
7	import { loadRawContext, type RawContext } from "@/lib/bank/raw-context";
8	import { organizationDescriptionKey, organizationDisplayName } from "@/lib/import/organization";
9	import { isInternalMove } from "@/lib/organize/identity";
10	import { wealthAmount } from "./wealth";
11	import { closingMovedTo } from "./account-closing";
12	import type { BankLeg } from "./transit";
13	
14	export const MATCH_DAYS = 3;
15	const CLOSING_MATCH_DAYS = 30;
16	const IBAN = /^[A-Z]{2}[0-9]{2}[A-Z0-9]{8,30}$/;
17	
18	export function normalizeIban(value: string) {
19	  const iban = value.replace(/\s/g, "").toUpperCase();
20	  return IBAN.test(iban) ? iban : null;
21	}
22	
23	export function sourceIbans(row: unknown) {
24	  if (!row || typeof row !== "object") return [];
25	  return Object.values(row).flatMap(value => typeof value === "string" ? [normalizeIban(value)].filter((iban): iban is string => Boolean(iban)) : []);
26	}
27	
28	export type TransferCandidate = {
29	  id: string; version: number; accountId: string; postedOn: string; amountMinor: bigint; currencyCode: string;
30	  reviewReasons: string[]; ibans: string[]; text?: string; counterparty?: string; transferId?: string | null;
31	  closingTo?: string;
32	  raw?: RawContext;
33	  identityId?: string | null;
34	};
35	
36	const CASH = /\b(bargeldauszahlung|bargeldeinzahlung|geldautomat|cash withdrawal|atm withdrawal|cash deposit)\b/i;
37	const SCALABLE = /\bscalable capital\b/i, SCALABLE_LABEL = /\bscalable\b/i;
38	export type NamedAccount = "cash" | "scalable";
39	export const NAMED_LABELS: Record<NamedAccount, string> = { cash: "Cash", scalable: "Scalable Capital" };
40	export type OwnAccounts = { tracked: Map<string, string>; untracked: Map<string, string>;
41	  ids?: Map<string, string> };
42	
43	const days = (a: string, b: string) => Math.abs(Date.parse(a) - Date.parse(b)) / 86400000;
44	
45	export type Leg = Pick<TransferCandidate, "id" | "accountId" | "postedOn" | "amountMinor" | "currencyCode">;
46	
47	export function findOwnTransfers(rows: TransferCandidate[], own: OwnAccounts, legs: Leg[] = rows, options: { scalable?: boolean } = {}) {
48	  const counterparts = (row: TransferCandidate) => row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
49	  const points = (row: TransferCandidate, accountId: string) => row.closingTo === accountId || counterparts(row).some(iban => own.tracked.get(iban) === accountId)
50	    || !!row.raw?.counterparty_ids.some(id => own.ids?.get(id.identification) === accountId);
51	  const matches = (out: TransferCandidate, into: TransferCandidate) => out.amountMinor < 0n && into.amountMinor === -out.amountMinor
52	    && out.currencyCode === into.currencyCode && out.accountId !== into.accountId && days(out.postedOn, into.postedOn) <= (out.closingTo || into.closingTo ? CLOSING_MATCH_DAYS : MATCH_DAYS);
53	  const used = new Set<string>();
54	  const pairs: { outId: string; inId: string }[] = [];
55	  const outs = rows.filter(row => row.amountMinor < 0n), ins = rows.filter(row => row.amountMinor > 0n);
56	  const take = (out: TransferCandidate, into: TransferCandidate) => { used.add(out.id); used.add(into.id); pairs.push({ outId: out.id, inId: into.id }); };
57	
58	  for (const out of outs) {
59	    const proven = ins.filter(into => !used.has(into.id) && matches(out, into) && (points(out, into.accountId) || points(into, out.accountId)))
60	      .sort((a, b) => days(out.postedOn, a.postedOn) - days(out.postedOn, b.postedOn) || a.id.localeCompare(b.id));
61	    const tied = proven[1] && days(out.postedOn, proven[1].postedOn) === days(out.postedOn, proven[0].postedOn);
62	    if (!used.has(out.id) && proven[0] && !tied) take(out, proven[0]);
63	  }
64	  const unpaired = (row: TransferCandidate, accountId: string) => !legs.some(other => other.id !== row.id && other.accountId === accountId
65	    && other.currencyCode === row.currencyCode && other.amountMinor === -row.amountMinor && days(row.postedOn, other.postedOn) <= MATCH_DAYS);
66	  const single = rows.flatMap((row): { transactionId: string; identifierId?: string; iban?: string }[] => {
67	    if (used.has(row.id)) return [];
68	    const identifierId = counterparts(row).map(iban => own.untracked.get(iban)).find(Boolean);
69	    if (identifierId) return [{ transactionId: row.id, identifierId }];
70	    const iban = counterparts(row).find(item => own.tracked.has(item));
71	    const accountId = iban ? own.tracked.get(iban) : undefined;
72	    return iban && accountId && unpaired(row, accountId) ? [{ transactionId: row.id, iban }] : [];
73	  });
74	  const marked = new Set(single.map(item => item.transactionId));
75	  const named = rows.flatMap((row): { transactionId: string; account: NamedAccount }[] => {
76	    if (used.has(row.id) || marked.has(row.id) || counterparts(row).some(iban => own.tracked.has(iban) || own.untracked.has(iban))) return [];
77	    if (CASH.test(row.text ?? "")) return [{ transactionId: row.id, account: "cash" }];
78	    if (options.scalable && SCALABLE.test(`${row.counterparty ?? ""} ${row.text ?? ""}`)) return [{ transactionId: row.id, account: "scalable" }];
79	    return [];
80	  });
81	  return { pairs, single, named };
82	}
83	
84	const OUTSIDE = new Set(["card", "direct_debit", "cash", "fee_interest"]);
85	const EXCHANGE_DAYS = 1;
86	const noOutsideParty = (row: TransferCandidate) => !!row.raw && !OUTSIDE.has(row.raw.payment_type) && !row.raw.counterparty_name && (!row.raw.counterparty_iban || row.raw.own_account);
87	
88	export function exchangeEvidence(row: TransferCandidate) {
89	  const raw = row.raw;
90	  if (!raw || OUTSIDE.has(raw.payment_type)) return false;
91	  return raw.payment_type === "exchange" || ((!!raw.exchange_rate || (!!raw.instructed_currency && raw.instructed_currency !== row.currencyCode)) && noOutsideParty(row));
92	}
93	
94	const instructedMinor = (row: TransferCandidate) => {
95	  try { return row.raw?.instructed_amount && row.raw.instructed_currency ? wealthAmount(row.raw.instructed_amount.replace(/^-/, ""), row.raw.instructed_currency) : null; } catch { return null; }
96	};
97	const magnitude = (amount: bigint) => amount < 0n ? -amount : amount;
98	
99	export function findExchanges(rows: TransferCandidate[]) {
100	  const stated = (a: TransferCandidate, b: TransferCandidate) => a.raw?.instructed_currency !== b.currencyCode || instructedMinor(a) === null || instructedMinor(a) === magnitude(b.amountMinor);
101	  const fits = (leg: TransferCandidate, other: TransferCandidate) => other.id !== leg.id && other.accountId !== leg.accountId && other.currencyCode !== leg.currencyCode
102	    && other.amountMinor !== 0n && (other.amountMinor < 0n) !== (leg.amountMinor < 0n) && days(leg.postedOn, other.postedOn) <= EXCHANGE_DAYS
103	    && (exchangeEvidence(other) || noOutsideParty(other)) && stated(leg, other) && stated(other, leg);
104	  const used = new Set<string>();
105	  const pairs: { outId: string; inId: string }[] = [], single: string[] = [];
106	  for (const leg of rows.filter(exchangeEvidence).sort((a, b) => a.id.localeCompare(b.id))) {
107	    if (used.has(leg.id)) continue;
108	    const others = rows.filter(other => !used.has(other.id) && fits(leg, other));
109	    const back = others.length === 1 ? rows.filter(item => !used.has(item.id) && fits(others[0], item)) : [];
110	    used.add(leg.id);
111	    if (back.length === 1) {
112	      used.add(others[0].id);
113	      pairs.push(leg.amountMinor < 0n ? { outId: leg.id, inId: others[0].id } : { outId: others[0].id, inId: leg.id });
114	    } else single.push(leg.id);
115	  }
116	  return { pairs, single };
117	}
118	
119	export function uncertainPairs(rows: TransferCandidate[]) {
120	  const outsider = (row: TransferCandidate) => !!row.raw && (OUTSIDE.has(row.raw.payment_type) || row.raw.payment_type === "exchange" || !!row.raw.counterparty_iban || !!row.raw.creditor_id);
121	  const open = rows.filter(row => !outsider(row));
122	  const matches = (out: TransferCandidate, into: TransferCandidate) => out.amountMinor < 0n && into.amountMinor === -out.amountMinor && out.currencyCode === into.currencyCode
123	    && out.accountId !== into.accountId && days(out.postedOn, into.postedOn) <= MATCH_DAYS;
124	  return open.flatMap(out => {
125	    const ins = open.filter(into => matches(out, into));
126	    return ins.length === 1 && open.filter(other => matches(other, ins[0])).length === 1 ? [{ outId: out.id, inId: ins[0].id }] : [];
127	  });
128	}
129	
130	export function internalMoves(rows: TransferCandidate[]) {
131	  const groups = new Map<string, TransferCandidate[]>();
132	  for (const row of rows) {
133	    const key = organizationDescriptionKey(row.text ?? "");
134	    if (!isInternalMove(row.raw) || key.length < 3) continue;
135	    groups.set(key, [...groups.get(key) ?? [], row]);
136	  }
137	  const bothWays = (items: TransferCandidate[]) => items.some(a => a.amountMinor < 0n && items.some(b => b.amountMinor > 0n && b.accountId === a.accountId));
138	  return [...groups].filter(([, items]) => bothWays(items) || items.some(item => ["transfer", "top_up"].includes(item.raw!.payment_type)))
139	    .map(([key, items]) => {
140	      const identities = new Set(items.map(item => item.identityId ?? null));
141	      return { key, transactionIds: items.map(item => item.id).sort().slice(0, 500), identityId: identities.size === 1 ? [...identities][0] : null };
142	    }).sort((a, b) => a.key.localeCompare(b.key));
143	}
144	
145	export const CASH_CARD_DAYS = 30;
146	export function cashWithdrawals<T extends Pick<TransferCandidate, "id" | "postedOn" | "amountMinor" | "text" | "transferId">>(rows: T[], today: string, answered = new Set<string>()) {
147	  return rows.filter(row => row.amountMinor < 0n && !row.transferId && CASH.test(row.text ?? "") && !answered.has(row.id) && days(row.postedOn, today) <= CASH_CARD_DAYS);
148	}
149	
150	const nameKey = (name: string) => name.normalize("NFD").replace(/\p{M}/gu, "").replace(/\s+/g, " ").trim().toLowerCase();
151	
152	export function ownNameSuggestions(rows: TransferCandidate[], seen: TransferCandidate[], own: OwnAccounts, answered = new Set<string>()) {
153	  const names = new Map<string, string>();
154	  for (const row of seen) {
155	    const other = row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
156	    if (row.counterparty?.trim() && other.some(iban => own.tracked.has(iban) || own.untracked.has(iban))) names.set(nameKey(row.counterparty), row.counterparty.trim());
157	  }
158	  return rows.flatMap(row => {
159	    const name = row.counterparty ? names.get(nameKey(row.counterparty)) : undefined;
160	    return name && !answered.has(row.id) && nameKey(row.text ?? "").includes(nameKey(name)) ? [{ transactionId: row.id, name }] : [];
161	  });
162	}
