164	const PAGE = 1000, MAX_ROWS = 5000;
165	
166	export async function loadOwnAccounts(db: SupabaseClient, workspaceId: string): Promise<OwnAccounts> {
167	  const [identifiers, bank, accounts] = await Promise.all([
168	    db.from("own_account_identifiers").select("id, account_id, iban").eq("workspace_id", workspaceId),
169	    db.from("bank_connection_accounts").select("iban, account_name, currency_code").eq("workspace_id", workspaceId).not("iban", "is", null),
170	    db.from("accounts").select("id, name, currency_code").eq("workspace_id", workspaceId),
171	  ]);
172	  for (const result of [identifiers, bank, accounts]) if (result.error) throw new Error(result.error.message);
173	  const tracked = new Map<string, string>(), untracked = new Map<string, string>();
174	  for (const row of bank.data ?? []) {
175	    const account = accounts.data?.find(item => item.name === row.account_name && item.currency_code === row.currency_code);
176	    const iban = normalizeIban(row.iban ?? "");
177	    if (account && iban) tracked.set(iban, account.id);
178	  }
179	  for (const row of identifiers.data ?? []) {
180	    if (row.account_id) tracked.set(row.iban, row.account_id); else untracked.set(row.iban, row.id);
181	  }
182	  return { tracked, untracked };
183	}
184	
185	type Row = { id: string; version: number; account_id: string; posted_on: string; amount_minor: string; currency_code: string; review_reasons: string[] | null; description: string; transfer_id: string | null; identity_id: string | null;
186	  transaction_sources: { source_transactions: { original_row: unknown } | null }[] | null };
187	
188	const counterpartyOf = (row: unknown) => {
189	  const value = row && typeof row === "object" ? (row as { counterparty?: unknown }).counterparty : undefined;
190	  return typeof value === "string" && value.trim() ? value.trim() : undefined;
191	};
192	
193	async function loadRows(db: SupabaseClient, workspaceId: string, kind: "ordinary" | "transfer") {
194	  const rows: TransferCandidate[] = [];
195	  for (let from = 0; from < MAX_ROWS; from += PAGE) {
196	    let query = db.from("transactions")
197	      .select("id, version, account_id, posted_on, amount_minor::text, currency_code, review_reasons, description, transfer_id, identity_id, transaction_sources(source_transactions(original_row))")
198	      .eq("workspace_id", workspaceId).eq("status", "posted").eq("kind", kind);
199	    if (kind === "ordinary") query = query.is("transfer_id", null).is("refund_of_id", null);
200	    const { data, error } = await query.order("posted_on", { ascending: false }).order("id").range(from, from + PAGE - 1);
201	    if (error) throw new Error(error.message);
202	    for (const row of (data ?? []) as unknown as Row[]) {
203	      const reviewReasons = row.review_reasons ?? [];
204	      if (kind === "ordinary" && reviewReasons.some(reason => reason !== "source_transfer")) continue;
205	      const originals = (row.transaction_sources ?? []).map(source => source.source_transactions?.original_row);
206	      rows.push({ id: row.id, version: row.version, accountId: row.account_id, postedOn: row.posted_on, amountMinor: BigInt(row.amount_minor),
207	        currencyCode: row.currency_code, reviewReasons, ibans: [...new Set(originals.flatMap(sourceIbans))], text: row.description, counterparty: originals.map(counterpartyOf).find(Boolean), transferId: row.transfer_id, identityId: row.identity_id });
208	    }
209	    if ((data ?? []).length < PAGE) break;
210	  }
211	  return rows;
212	}
213	
214	export const loadTransferCandidates = (db: SupabaseClient, workspaceId: string) => loadRows(db, workspaceId, "ordinary");
215	
216	export async function loadTransferLegs(db: SupabaseClient, workspaceId: string): Promise<BankLeg[]> {
217	  const [rows, own, identifiers] = await Promise.all([loadRows(db, workspaceId, "transfer"), loadOwnAccounts(db, workspaceId),
218	    db.from("own_account_identifiers").select("iban, label").eq("workspace_id", workspaceId)]);
219	  if (identifiers.error) throw new Error(identifiers.error.message);
220	  const brokerIbans = new Set((identifiers.data ?? []).filter(row => SCALABLE_LABEL.test(row.label)).map(row => row.iban as string));
221	  return rows.map(row => ({ id: row.id, accountId: row.accountId, amountMinor: row.amountMinor, currencyCode: row.currencyCode, postedOn: row.postedOn, transferId: row.transferId ?? null, text: row.text,
222	    provesBroker: row.ibans.some(iban => brokerIbans.has(iban)) || SCALABLE.test(`${row.counterparty ?? ""} ${row.text ?? ""}`),
223	    ownAccount: row.ibans.some(iban => own.tracked.has(iban) && own.tracked.get(iban) !== row.accountId) }));
224	}
225	
226	async function loadLegs(db: SupabaseClient, workspaceId: string): Promise<Leg[]> {
227	  const legs: Leg[] = [];
228	  for (let from = 0; from < MAX_ROWS; from += PAGE) {
229	    const { data, error } = await db.from("transactions")
230	      .select("id, account_id, posted_on, amount_minor::text, currency_code")
231	      .eq("workspace_id", workspaceId).eq("status", "posted").order("id").range(from, from + PAGE - 1);
232	    if (error) throw new Error(error.message);
233	    for (const row of data ?? []) legs.push({ id: row.id, accountId: row.account_id, postedOn: row.posted_on, amountMinor: BigInt(row.amount_minor), currencyCode: row.currency_code });
234	    if ((data ?? []).length < PAGE) break;
235	  }
236	  return legs;
237	}
