239	export const ownTransferPayloadSchema = z.union([z.object({ transactionId: z.uuid(), name: z.string().trim().min(1).max(120) }).strict(),
240	  z.object({ transactionId: z.uuid(), pairWith: z.uuid() }).strict()]);
