242	async function proposeOwnNames(db: SupabaseClient, workspaceId: string, rows: TransferCandidate[], seen: TransferCandidate[], own: OwnAccounts) {
243	  const known = await db.from("agent_proposals").select("conflict_key").eq("workspace_id", workspaceId).is("run_id", null).eq("kind", "own_transfer").limit(5000);
244	  if (known.error) throw new Error(known.error.message);
245	  const answered = new Set((known.data ?? []).map(row => String(row.conflict_key).replace(/^own_transfer:/, "")));
246	  const found = ownNameSuggestions(rows, seen, own, answered);
247	  if (!found.length) return 0;
248	  const { locale } = await loadWorkspaceSettings(db, workspaceId);
249	  const byId = new Map(rows.map(row => [row.id, row]));
250	  const cards = found.map(({ transactionId, name }) => {
251	    const row = byId.get(transactionId)!, money = formatMoney(row.amountMinor < 0n ? -row.amountMinor : row.amountMinor, row.currencyCode, locale);
252	    return { workspace_id: workspaceId, agent: "chat", kind: "own_transfer", conflict_key: `own_transfer:${transactionId}`, confidence: 70,
253	      title: (row.amountMinor < 0n ? `${money} to ${name}: your own account?` : `${money} from ${name}: your own account?`).slice(0, 200),
254	      detail: `You sent money under the name ${name} to one of your own accounts before. If this is yours too, it moves to transfers and stops counting as ${row.amountMinor < 0n ? "spending" : "income"}.`,
255	      evidence: { facts: [], transactions: [{ id: row.id, date: row.postedOn, description: row.text ?? "", amountMinor: row.amountMinor.toString(), currency: row.currencyCode }], links: [] },
256	      payload: ownTransferPayloadSchema.parse({ transactionId, name }) };
257	  });
258	  const { data, error } = await db.from("agent_proposals").insert(cards).select("id");
259	  if (error && error.code !== "23505") throw new Error(error.message);
260	  return data?.length ?? 0;
261	}
262	
263	async function proposeCashWithdrawals(db: SupabaseClient, workspaceId: string, rows: TransferCandidate[]) {
264	  const { locale, timezone } = await loadWorkspaceSettings(db, workspaceId);
265	  const known = await db.from("agent_proposals").select("conflict_key").eq("workspace_id", workspaceId).is("run_id", null).eq("kind", "cash_withdrawal").limit(5000);
266	  if (known.error) throw new Error(known.error.message);
267	  const answered = new Set((known.data ?? []).map(row => String(row.conflict_key).replace(/^cash_withdrawal:/, "")));
268	  const found = cashWithdrawals(rows, calendarDate(new Date(), timezone), answered);
269	  if (!found.length) return 0;
270	  const cards = found.map(row => {
271	    const amount = -row.amountMinor, money = formatMoney(amount, row.currencyCode, locale);
272	    return { workspace_id: workspaceId, agent: "chat", kind: "cash_withdrawal", conflict_key: `cash_withdrawal:${row.id}`, confidence: 90,
273	      title: `${money} from a cash machine: add it to your Cash account?`.slice(0, 200),
274	      detail: "Until you add it, it counts as money that left. Once it's in Cash, your net worth stays the same; after spending, update the balance whenever you like.",
275	      evidence: { facts: [], transactions: [{ id: row.id, date: row.postedOn, description: row.text ?? "", amountMinor: row.amountMinor.toString(), currency: row.currencyCode }], links: [] },
276	      payload: { transactionId: row.id, amountMinor: amount.toString(), currencyCode: row.currencyCode, date: row.postedOn } };
277	  });
278	  const { data, error } = await db.from("agent_proposals").insert(cards).select("id");
279	  if (error && error.code !== "23505") throw new Error(error.message);
280	  return data?.length ?? 0;
281	}
282	
283	async function proposePairs(db: SupabaseClient, workspaceId: string, pairs: { outId: string; inId: string }[], byId: Map<string, TransferCandidate>, accounts: { id: string; name: string }[]) {
284	  if (!pairs.length) return 0;
285	  const known = await db.from("agent_proposals").select("conflict_key").eq("workspace_id", workspaceId).is("run_id", null).eq("kind", "own_transfer").limit(5000);
286	  if (known.error) throw new Error(known.error.message);
287	  const answered = new Set((known.data ?? []).map(row => String(row.conflict_key)));
288	  const fresh = pairs.filter(pair => !answered.has(`own_transfer:${pair.outId}:${pair.inId}`));
289	  if (!fresh.length) return 0;
290	  const { locale } = await loadWorkspaceSettings(db, workspaceId);
291	  const name = (id: string) => accounts.find(account => account.id === id)?.name ?? "another account";
292	  const cards = fresh.map(({ outId, inId }) => {
293	    const out = byId.get(outId)!, into = byId.get(inId)!, money = formatMoney(-out.amountMinor, out.currencyCode, locale);
294	    return { workspace_id: workspaceId, agent: "chat", kind: "own_transfer", conflict_key: `own_transfer:${outId}:${inId}`, confidence: 60,
295	      title: `${money} from ${name(out.accountId)} to ${name(into.accountId)}: moved between your accounts?`.slice(0, 200),
296	      detail: "The same amount left one of your accounts and arrived in another within a few days, but nothing from the bank proves both sides are yours. If they are, they become one transfer and stop counting as spending and income.",
297	      evidence: { facts: [], transactions: [out, into].map(row => ({ id: row.id, date: row.postedOn, description: row.text ?? "", amountMinor: row.amountMinor.toString(), currency: row.currencyCode })), links: [] },
298	      payload: ownTransferPayloadSchema.parse({ transactionId: outId, pairWith: inId }) };
299	  });
300	  const { data, error } = await db.from("agent_proposals").insert(cards).select("id");
301	  if (error && error.code !== "23505") throw new Error(error.message);
302	  return data?.length ?? 0;
303	}
