305	async function askAboutInternalMoves(db: SupabaseClient, workspaceId: string, moves: ReturnType<typeof internalMoves>) {
306	  for (const move of moves) {
307	    const { error } = await db.rpc("raise_organize_question", { p_workspace: workspaceId, p_identity_key: `internal:${move.key}`, p_identity_id: move.identityId,
308	      p_question: `"${organizationDisplayName(move.key)}" moves money with nobody else on the other side. What is it?`, p_transaction_ids: move.transactionIds, p_created_by: "system" });
309	    if (error) throw new Error(error.message);
310	  }
311	  return moves.length;
312	}
