314	export function withBankContext(rows: TransferCandidate[], raw: Map<string, RawContext>) {
315	  for (const row of rows) {
316	    row.raw = raw.get(row.id);
317	    const iban = normalizeIban(row.raw?.counterparty_iban ?? "");
318	    if (iban && !row.ibans.includes(iban)) row.ibans.push(iban);
319	  }
320	  return rows;
321	}
322	
323	function ownAccountIds(rows: TransferCandidate[]) {
324	  const ids = new Map<string, string | null>();
325	  for (const row of rows) for (const { identification } of row.raw?.own_side_ids ?? []) {
326	    const seen = ids.get(identification);
327	    ids.set(identification, seen === undefined || seen === row.accountId ? row.accountId : null);
328	  }
329	  return new Map([...ids].filter((entry): entry is [string, string] => entry[1] !== null));
330	}
331	
332	export async function linkOwnTransfers(db: SupabaseClient, workspaceId: string) {
333	  const [own, rows, legs, transfers, scalable] = await Promise.all([loadOwnAccounts(db, workspaceId), loadTransferCandidates(db, workspaceId), loadLegs(db, workspaceId),
334	    loadRows(db, workspaceId, "transfer"), db.from("scalable_connections").select("id", { count: "exact", head: true }).eq("workspace_id", workspaceId).eq("status", "active")]);
335	  if (scalable.error) throw new Error(scalable.error.message);
336	  const { data: accounts, error: accountsError } = await db.from("accounts").select("id, name, currency_code").eq("workspace_id", workspaceId);
337	  if (accountsError) throw new Error(accountsError.message);
338	  for (const row of rows) { const name = closingMovedTo(row.text); if (name) row.closingTo = accounts?.find(account => account.name === name && account.currency_code === row.currencyCode)?.id; }
339	  withBankContext(rows, await loadRawContext(db, workspaceId, rows.map(row => row.id)));
340	  own.ids = ownAccountIds(rows);
341	  const { pairs, single, named } = findOwnTransfers(rows, own, legs, { scalable: (scalable.count ?? 0) > 0 });
342	  const byId = new Map(rows.map(row => [row.id, row]));
343	  let linked = 0, marked = 0, skipped = 0;
344	  for (const pair of pairs) {
345	    const out = byId.get(pair.outId)!, into = byId.get(pair.inId)!;
346	    const { error } = await db.rpc("link_transactions", { p_operation: "transfer", p_primary_id: out.id, p_expected_version: out.version,
347	      p_other_id: into.id, p_other_version: into.version, p_fx_rate_id: null, p_fees: [], p_request_id: randomUUID() });
348	    if (error) skipped++; else linked++;
349	  }
350	  for (const item of single) {
351	    const expectedVersion = byId.get(item.transactionId)!.version;
352	    const { error } = item.identifierId
353	      ? await db.rpc("mark_own_account_transfer", { p_transaction_id: item.transactionId, p_expected_version: expectedVersion, p_identifier_id: item.identifierId })
354	      : await db.rpc("mark_own_iban_transfer", { p_transaction_id: item.transactionId, p_expected_version: expectedVersion, p_iban: item.iban });
355	    if (error) skipped++; else marked++;
356	  }
357	  for (const item of named) {
358	    const { error } = await db.rpc("mark_own_named_transfer", { p_transaction_id: item.transactionId, p_expected_version: byId.get(item.transactionId)!.version, p_kind: item.account });
359	    if (error) skipped++; else marked++;
360	  }
361	  const handled = new Set([...pairs.flatMap(pair => [pair.outId, pair.inId]), ...single.map(item => item.transactionId), ...named.map(item => item.transactionId)]);
362	  const exchanges = findExchanges(rows.filter(row => !handled.has(row.id)));
363	  const exchangeLegs: [string, string | null][] = [...exchanges.pairs.flatMap((pair): [string, string][] => [[pair.outId, pair.inId], [pair.inId, pair.outId]]),
364	    ...exchanges.single.map((id): [string, null] => [id, null])];
365	  for (const [id, other] of exchangeLegs) {
366	    const { error } = await db.rpc("mark_own_exchange", { p_transaction_id: id, p_expected_version: byId.get(id)!.version, p_counterpart_id: other });
367	    if (error) skipped++; else marked++;
368	    handled.add(id);
369	  }
370	  const unproven = uncertainPairs(rows.filter(row => !handled.has(row.id)));
371	  const pairCards = await proposePairs(db, workspaceId, unproven, byId, accounts ?? []);
372	  for (const pair of unproven) { handled.add(pair.outId); handled.add(pair.inId); }
373	  const questions = await askAboutInternalMoves(db, workspaceId, internalMoves(rows.filter(row => !handled.has(row.id))));
374	  const suggested = await proposeOwnNames(db, workspaceId, rows.filter(row => !handled.has(row.id)), [...rows, ...transfers], own);
375	  const cashCards = await proposeCashWithdrawals(db, workspaceId, [...rows.filter(row => !handled.has(row.id) || named.some(item => item.transactionId === row.id && item.account === "cash")), ...transfers]);
376	  return { linked, marked, skipped, suggested: suggested + pairCards, cashCards, questions };
377	}
