1	import { randomUUID } from "node:crypto";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	import { z } from "zod";
4	import { calendarDate } from "@/lib/finance/calendar";
5	import { formatMoney } from "@/lib/finance/format";
6	import { loadWorkspaceSettings } from "@/lib/settings";
7	import { loadRawContext, type RawContext } from "@/lib/bank/raw-context";
8	import { organizationDescriptionKey, organizationDisplayName } from "@/lib/import/organization";
9	import { isInternalMove } from "@/lib/organize/identity";
10	import { wealthAmount } from "./wealth";
11	import { closingMovedTo } from "./account-closing";
12	import type { BankLeg } from "./transit";
13	
14	export const MATCH_DAYS = 3;
15	const CLOSING_MATCH_DAYS = 30;
16	const IBAN = /^[A-Z]{2}[0-9]{2}[A-Z0-9]{8,30}$/;
17	
18	export function normalizeIban(value: string) {
19	  const iban = value.replace(/\s/g, "").toUpperCase();
20	  return IBAN.test(iban) ? iban : null;
21	}
22	
23	export function sourceIbans(row: unknown) {
24	  if (!row || typeof row !== "object") return [];
25	  return Object.values(row).flatMap(value => typeof value === "string" ? [normalizeIban(value)].filter((iban): iban is string => Boolean(iban)) : []);
26	}
27	
28	export type TransferCandidate = {
29	  id: string; version: number; accountId: string; postedOn: string; amountMinor: bigint; currencyCode: string;
30	  reviewReasons: string[]; ibans: string[]; text?: string; counterparty?: string; transferId?: string | null;
31	  closingTo?: string;
32	  raw?: RawContext;
33	  identityId?: string | null;
34	};
