36	const CASH = /\b(bargeldauszahlung|bargeldeinzahlung|geldautomat|cash withdrawal|atm withdrawal|cash deposit)\b/i;
37	const SCALABLE = /\bscalable capital\b/i, SCALABLE_LABEL = /\bscalable\b/i;
38	export type NamedAccount = "cash" | "scalable";
39	export const NAMED_LABELS: Record<NamedAccount, string> = { cash: "Cash", scalable: "Scalable Capital" };
40	export type OwnAccounts = { tracked: Map<string, string>; untracked: Map<string, string>;
41	  ids?: Map<string, string> };
