47	export function findOwnTransfers(rows: TransferCandidate[], own: OwnAccounts, legs: Leg[] = rows, options: { scalable?: boolean } = {}) {
48	  const counterparts = (row: TransferCandidate) => row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
49	  const points = (row: TransferCandidate, accountId: string) => row.closingTo === accountId || counterparts(row).some(iban => own.tracked.get(iban) === accountId)
50	    || !!row.raw?.counterparty_ids.some(id => own.ids?.get(id.identification) === accountId);
51	  const matches = (out: TransferCandidate, into: TransferCandidate) => out.amountMinor < 0n && into.amountMinor === -out.amountMinor
52	    && out.currencyCode === into.currencyCode && out.accountId !== into.accountId && days(out.postedOn, into.postedOn) <= (out.closingTo || into.closingTo ? CLOSING_MATCH_DAYS : MATCH_DAYS);
53	  const used = new Set<string>();
54	  const pairs: { outId: string; inId: string }[] = [];
55	  const outs = rows.filter(row => row.amountMinor < 0n), ins = rows.filter(row => row.amountMinor > 0n);
56	  const take = (out: TransferCandidate, into: TransferCandidate) => { used.add(out.id); used.add(into.id); pairs.push({ outId: out.id, inId: into.id }); };
57	
58	  for (const out of outs) {
59	    const proven = ins.filter(into => !used.has(into.id) && matches(out, into) && (points(out, into.accountId) || points(into, out.accountId)))
60	      .sort((a, b) => days(out.postedOn, a.postedOn) - days(out.postedOn, b.postedOn) || a.id.localeCompare(b.id));
61	    const tied = proven[1] && days(out.postedOn, proven[1].postedOn) === days(out.postedOn, proven[0].postedOn);
62	    if (!used.has(out.id) && proven[0] && !tied) take(out, proven[0]);
63	  }
64	  const unpaired = (row: TransferCandidate, accountId: string) => !legs.some(other => other.id !== row.id && other.accountId === accountId
65	    && other.currencyCode === row.currencyCode && other.amountMinor === -row.amountMinor && days(row.postedOn, other.postedOn) <= MATCH_DAYS);
66	  const single = rows.flatMap((row): { transactionId: string; identifierId?: string; iban?: string }[] => {
67	    if (used.has(row.id)) return [];
68	    const identifierId = counterparts(row).map(iban => own.untracked.get(iban)).find(Boolean);
69	    if (identifierId) return [{ transactionId: row.id, identifierId }];
70	    const iban = counterparts(row).find(item => own.tracked.has(item));
71	    const accountId = iban ? own.tracked.get(iban) : undefined;
72	    return iban && accountId && unpaired(row, accountId) ? [{ transactionId: row.id, iban }] : [];
73	  });
74	  const marked = new Set(single.map(item => item.transactionId));
75	  const named = rows.flatMap((row): { transactionId: string; account: NamedAccount }[] => {
76	    if (used.has(row.id) || marked.has(row.id) || counterparts(row).some(iban => own.tracked.has(iban) || own.untracked.has(iban))) return [];
77	    if (CASH.test(row.text ?? "")) return [{ transactionId: row.id, account: "cash" }];
78	    if (options.scalable && SCALABLE.test(`${row.counterparty ?? ""} ${row.text ?? ""}`)) return [{ transactionId: row.id, account: "scalable" }];
79	    return [];
80	  });
81	  return { pairs, single, named };
82	}
