84	const OUTSIDE = new Set(["card", "direct_debit", "cash", "fee_interest"]);
85	const EXCHANGE_DAYS = 1;
86	const noOutsideParty = (row: TransferCandidate) => !!row.raw && !OUTSIDE.has(row.raw.payment_type) && !row.raw.counterparty_name && (!row.raw.counterparty_iban || row.raw.own_account);
87	
88	export function exchangeEvidence(row: TransferCandidate) {
89	  const raw = row.raw;
90	  if (!raw || OUTSIDE.has(raw.payment_type)) return false;
91	  return raw.payment_type === "exchange" || ((!!raw.exchange_rate || (!!raw.instructed_currency && raw.instructed_currency !== row.currencyCode)) && noOutsideParty(row));
92	}
93	
94	const instructedMinor = (row: TransferCandidate) => {
95	  try { return row.raw?.instructed_amount && row.raw.instructed_currency ? wealthAmount(row.raw.instructed_amount.replace(/^-/, ""), row.raw.instructed_currency) : null; } catch { return null; }
96	};
97	const magnitude = (amount: bigint) => amount < 0n ? -amount : amount;
98	
99	export function findExchanges(rows: TransferCandidate[]) {
100	  const stated = (a: TransferCandidate, b: TransferCandidate) => a.raw?.instructed_currency !== b.currencyCode || instructedMinor(a) === null || instructedMinor(a) === magnitude(b.amountMinor);
101	  const fits = (leg: TransferCandidate, other: TransferCandidate) => other.id !== leg.id && other.accountId !== leg.accountId && other.currencyCode !== leg.currencyCode
102	    && other.amountMinor !== 0n && (other.amountMinor < 0n) !== (leg.amountMinor < 0n) && days(leg.postedOn, other.postedOn) <= EXCHANGE_DAYS
103	    && (exchangeEvidence(other) || noOutsideParty(other)) && stated(leg, other) && stated(other, leg);
104	  const used = new Set<string>();
105	  const pairs: { outId: string; inId: string }[] = [], single: string[] = [];
106	  for (const leg of rows.filter(exchangeEvidence).sort((a, b) => a.id.localeCompare(b.id))) {
107	    if (used.has(leg.id)) continue;
108	    const others = rows.filter(other => !used.has(other.id) && fits(leg, other));
109	    const back = others.length === 1 ? rows.filter(item => !used.has(item.id) && fits(others[0], item)) : [];
110	    used.add(leg.id);
111	    if (back.length === 1) {
112	      used.add(others[0].id);
113	      pairs.push(leg.amountMinor < 0n ? { outId: leg.id, inId: others[0].id } : { outId: others[0].id, inId: leg.id });
114	    } else single.push(leg.id);
115	  }
116	  return { pairs, single };
117	}
