152	export function ownNameSuggestions(rows: TransferCandidate[], seen: TransferCandidate[], own: OwnAccounts, answered = new Set<string>()) {
153	  const names = new Map<string, string>();
154	  for (const row of seen) {
155	    const other = row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
156	    if (row.counterparty?.trim() && other.some(iban => own.tracked.has(iban) || own.untracked.has(iban))) names.set(nameKey(row.counterparty), row.counterparty.trim());
157	  }
158	  return rows.flatMap(row => {
159	    const name = row.counterparty ? names.get(nameKey(row.counterparty)) : undefined;
160	    return name && !answered.has(row.id) && nameKey(row.text ?? "").includes(nameKey(name)) ? [{ transactionId: row.id, name }] : [];
161	  });
162	}
