1	-- Own money that arrives or leaves without an IBAN: a cash machine, Scalable Capital (its broker
2	-- withdrawals carry no IBAN), or an old account of the owner known only by their name on it.
3	-- Same audit as mark_own_account_transfer (operation own_account_transfer, no identifier), so
4	-- undo_own_account_transfer restores the row exactly.
5	--   cash      the bank's wording says cash machine; background jobs may mark it.
6	--   scalable  the owner connected Scalable; background jobs may mark it.
7	--   owner     only the signed-in owner, by accepting an own_transfer card (a name is weak evidence).
8	create function public.mark_own_named_transfer(
9	  p_transaction_id uuid,
10	  p_expected_version integer,
11	  p_kind text,
12	  p_label text default null
13	) returns public.transactions
14	language plpgsql security definer set search_path = '' as $$
15	declare
16	  actor uuid;
17	  old_row public.transactions%rowtype;
18	  new_row public.transactions%rowtype;
19	  own_label text;
20	begin
21	  if auth.uid() is null and (select auth.jwt()->>'role') is distinct from 'service_role' then raise exception 'Authentication required' using errcode = '28000'; end if;
22	  if p_kind is null or p_kind not in ('cash', 'scalable', 'owner') then raise exception 'Unknown own account' using errcode = '22023'; end if;
23	  if p_kind = 'owner' and auth.uid() is null then raise exception 'Only the owner can confirm this' using errcode = '42501'; end if;
24	  select * into old_row from public.transactions
25	  where id = p_transaction_id and public.can_link_workspace(workspace_id) for update;
26	  if not found then raise exception 'Transaction not found' using errcode = 'P0002'; end if;
27	  actor := public.link_actor(old_row.workspace_id);
28	  if p_kind = 'scalable' and not exists (select 1 from public.scalable_connections where workspace_id = old_row.workspace_id and status = 'active') then
29	    raise exception 'Scalable Capital is not connected' using errcode = '22023';
30	  end if;
31	  own_label := case p_kind when 'cash' then 'Cash' when 'scalable' then 'Scalable Capital' else btrim(coalesce(p_label, '')) end;
32	  if char_length(own_label) not between 1 and 120 then raise exception 'Name the own account' using errcode = '22023'; end if;
33	  if old_row.version is distinct from p_expected_version then
34	    raise exception 'Transaction changed; refresh and retry' using errcode = 'PT409';
35	  end if;
36	  if old_row.status <> 'posted' or old_row.kind <> 'ordinary' or old_row.transfer_id is not null or old_row.refund_of_id is not null
37	    or old_row.amount_minor = 0 or not (old_row.review_reasons <@ array['source_transfer']::text[])
38	    or exists (select 1 from public.transactions where refund_of_id = old_row.id or transfer_id = old_row.id)
39	    or exists (select 1 from public.transaction_split_sets where transaction_id = old_row.id and undone_at is null)
40	    or exists (select 1 from public.transaction_links where undone_at is null and (primary_transaction_id = old_row.id or counterpart_transaction_id = old_row.id))
41	  then raise exception 'Only posted, unlinked, unsplit transactions can be marked' using errcode = '22023'; end if;
42	
43	  update public.transactions set kind = 'transfer', review_reasons = '{}', version = version + 1
44	  where id = old_row.id returning * into new_row;
45	  insert into public.correction_events (workspace_id, transaction_id, actor_id, before, after)
46	  values (old_row.workspace_id, old_row.id, actor,
47	    jsonb_build_object('category_id', old_row.category_id, 'note', old_row.note, 'kind', old_row.kind,
48	      'transfer_id', old_row.transfer_id, 'refund_of_id', old_row.refund_of_id,
49	      'review_reasons', to_jsonb(old_row.review_reasons), 'version', old_row.version),
50	    jsonb_build_object('category_id', new_row.category_id, 'note', new_row.note, 'kind', new_row.kind,
51	      'transfer_id', new_row.transfer_id, 'refund_of_id', new_row.refund_of_id,
52	      'review_reasons', to_jsonb(new_row.review_reasons), 'version', new_row.version,
53	      'operation', 'own_account_transfer', 'identifier_id', null, 'own_account', own_label, 'rule', p_kind));
54	  return new_row;
55	end;
