6	-- bank that is not imported). Bank-connected accounts already carry their IBAN in
7	-- bank_connection_accounts; this table covers everything else.
8	create table public.own_account_identifiers (
9	  id uuid primary key default gen_random_uuid(),
10	  workspace_id uuid not null references public.workspaces(id) on delete cascade,
11	  account_id uuid references public.accounts(id) on delete cascade,
12	  iban text not null check (iban ~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{8,30}$'),
13	  label text not null check (char_length(btrim(label)) between 1 and 120),
14	  created_at timestamptz not null default now(),
15	  unique (workspace_id, iban)
16	);
17	
18	alter table public.own_account_identifiers enable row level security;
19	create policy own_account_identifiers_owned on public.own_account_identifiers for all to authenticated
20	using (public.owns_workspace(workspace_id))
21	with check (public.owns_workspace(workspace_id)
22	  and (account_id is null or exists (select 1 from public.accounts where id = account_id and workspace_id = own_account_identifiers.workspace_id)));
23	grant select, insert, delete on public.own_account_identifiers to authenticated;
24	
25	-- One leg of a transfer whose other side is an own account Moneo does not track.
26	-- kind='transfer' with no transfer_id; the source review flag 'source_transfer' is
27	-- resolved by this decision. Audited as a correction event and undone with
28	-- undo_own_account_transfer, which restores kind and review flags exactly.
29	create function public.mark_own_account_transfer(
30	  p_transaction_id uuid,
31	  p_expected_version integer,
32	  p_identifier_id uuid
33	) returns public.transactions
34	language plpgsql security definer set search_path = '' as $$
35	declare
36	  actor uuid := auth.uid();
37	  old_row public.transactions%rowtype;
38	  new_row public.transactions%rowtype;
39	  identifier public.own_account_identifiers%rowtype;
40	begin
41	  if actor is null then raise exception 'Authentication required' using errcode = '28000'; end if;
42	  select * into old_row from public.transactions
43	  where id = p_transaction_id and public.owns_workspace(workspace_id) for update;
44	  if not found then raise exception 'Transaction not found' using errcode = 'P0002'; end if;
45	  select * into identifier from public.own_account_identifiers
46	  where id = p_identifier_id and workspace_id = old_row.workspace_id and account_id is null;
47	  if not found then raise exception 'Own untracked account not found' using errcode = 'P0002'; end if;
48	  if old_row.version is distinct from p_expected_version then
49	    raise exception 'Transaction changed; refresh and retry' using errcode = '40001';
50	  end if;
51	  if old_row.status <> 'posted' or old_row.kind <> 'ordinary' or old_row.transfer_id is not null or old_row.refund_of_id is not null
52	    or old_row.amount_minor = 0 or not (old_row.review_reasons <@ array['source_transfer']::text[])
53	    or exists (select 1 from public.transactions where refund_of_id = old_row.id or transfer_id = old_row.id)
54	    or exists (select 1 from public.transaction_split_sets where transaction_id = old_row.id and undone_at is null)
55	    or exists (select 1 from public.transaction_links where undone_at is null and (primary_transaction_id = old_row.id or counterpart_transaction_id = old_row.id))
56	  then raise exception 'Only posted, unlinked, unsplit transactions can be marked' using errcode = '22023'; end if;
57	
58	  update public.transactions set kind = 'transfer', review_reasons = '{}', version = version + 1
59	  where id = old_row.id returning * into new_row;
60	  insert into public.correction_events (workspace_id, transaction_id, actor_id, before, after)
61	  values (old_row.workspace_id, old_row.id, actor,
62	    jsonb_build_object('category_id', old_row.category_id, 'note', old_row.note, 'kind', old_row.kind,
63	      'transfer_id', old_row.transfer_id, 'refund_of_id', old_row.refund_of_id,
64	      'review_reasons', to_jsonb(old_row.review_reasons), 'version', old_row.version),
65	    jsonb_build_object('category_id', new_row.category_id, 'note', new_row.note, 'kind', new_row.kind,
66	      'transfer_id', new_row.transfer_id, 'refund_of_id', new_row.refund_of_id,
67	      'review_reasons', to_jsonb(new_row.review_reasons), 'version', new_row.version,
68	      'operation', 'own_account_transfer', 'identifier_id', identifier.id, 'own_account', identifier.label));
69	  return new_row;
70	end;
71	$$;
72	
73	create function public.undo_own_account_transfer(
74	  p_event_id uuid,
75	  p_expected_version integer
76	) returns public.transactions
77	language plpgsql security definer set search_path = '' as $$
78	declare
79	  actor uuid := auth.uid();
80	  event_row public.correction_events%rowtype;
81	  old_row public.transactions%rowtype;
82	  new_row public.transactions%rowtype;
83	begin
84	  if actor is null then raise exception 'Authentication required' using errcode = '28000'; end if;
85	  select * into event_row from public.correction_events
86	  where id = p_event_id and public.owns_workspace(workspace_id) and after->>'operation' = 'own_account_transfer';
87	  if not found then raise exception 'Correction not found' using errcode = 'P0002'; end if;
88	  select * into old_row from public.transactions
89	  where id = event_row.transaction_id and workspace_id = event_row.workspace_id for update;
90	  if old_row.version is distinct from p_expected_version or event_row.undone
91	    or old_row.version is distinct from (event_row.after->>'version')::integer
92	    or old_row.kind <> 'transfer' or old_row.transfer_id is not null then
93	    raise exception 'Transaction changed; refresh and retry' using errcode = '40001';
94	  end if;
95	  update public.transactions
96	  set kind = event_row.before->>'kind',
97	      review_reasons = array(select jsonb_array_elements_text(event_row.before->'review_reasons')),
98	      version = version + 1
99	  where id = old_row.id returning * into new_row;
100	  update public.correction_events set undone = true where id = p_event_id;
101	  return new_row;
102	end;
103	$$;
104	
105	revoke all on function public.mark_own_account_transfer(uuid, integer, uuid) from public, anon;
106	revoke all on function public.undo_own_account_transfer(uuid, integer) from public, anon;
107	grant execute on function public.mark_own_account_transfer(uuid, integer, uuid) to authenticated;
108	grant execute on function public.undo_own_account_transfer(uuid, integer) to authenticated;
